// Configure PDF.js worker using standard robust same-origin Blob workaround to prevent blocking��पिंग सेवाओं और व्यावसायिक पंजीकरण के लिए आपका वन-स्टॉप समाधान। हम कागजी कार्रवाई संभालते हैं ताकि आपको ऐसा न करना पड़े।",


// Configure PDF.js worker using standard robust same-origin Blob workaround to prevent blocking
if (typeof window !== "undefined") {
  try {
    if (pdfjsLib && pdfjsLib.GlobalWorkerOptions) {
      const workerUrl = "https://unpkg.com/pdfjs-dist@5.7.284/build/pdf.worker.min.mjs";
      const blobCode = `importScripts('${workerUrl}');`;
      const blob = new Blob([blobCode], { type: "application/javascript" });
      pdfjsLib.GlobalWorkerOptions.workerSrc = URL.createObjectURL(blob);
    }
  } catch (err) {
    console.warn("PDF worker CDN Blob configuration skipped:", err);
  }
}

