// --- HELPERS ---
const fetchQrCodeBase64 = async (data: string): Promise<string> => {
  try {
    const url = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(data)}`;
    const response = await fetch(url);
    const blob = await response.blob();
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result as string);
      reader.readAsDataURL(blob);
    });
  } catch (err) {
    console.error("fetchQrCodeBase64 error:", err);
    return "";
  }
};

const getTransactionHash = (item: any) => {
  const raw = `${item.ID || item.orderId || ''}-${item.UserEmail || item.userEmail || ''}-${item.Timestamp || item.date || ''}`;
  const hash = raw.split('').reduce((acc, char) => acc + char.charCodeAt(0), 17);
  return "0x" + Math.abs(hash).toString(16).padStart(8, '0') + "ca9e9b88ad3e" + Math.abs(hash * 3).toString(16).substring(0, 8);
};

const generateCompletionCertificate = async (item: any) => {
  const toastId = toast.loading("Verifying completion and preparing official certificate...");
  try {
    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4"
    });

    const orderIdVal = item.orderId || item.ID || item.ApplicationID || "N/A";
    const serviceName = item.service || item.Type || item.ServiceType || "Administrative Service";
    const userEmail = item.UserEmail || item.userEmail || item.Email || "Customer";
    const rawDateVal = item.createdAt || item.CreatedAt || item.timestamp || item.Timestamp || item.date || item.Date;
    const parsedDate = rawDateVal ? new Date(rawDateVal) : new Date();
    const dateVal = isNaN(parsedDate.getTime()) ? new Date().toLocaleDateString() : parsedDate.toLocaleDateString();
    const hash = getTransactionHash(item);

    // Obtain server-side verified digital watermark & cryptographic signature
    let serverWatermark = "AOS DIGITAL SEAL • VERIFIED";
    let serverHash = hash;
    let qrTargetUrl = window.location.origin + "/?tab=tracking&orderId=" + encodeURIComponent(orderIdVal);
    try {
      const signRes = await axios.post("/api/certificate/sign-watermark", {
        orderId: orderIdVal,
        serviceName,
        userEmail
      });
      if (signRes.data?.success && signRes.data?.data) {
        serverWatermark = signRes.data.data.watermarkText || serverWatermark;
        serverHash = signRes.data.data.shortHash || serverHash;
        qrTargetUrl = signRes.data.data.qrVerificationUrl || qrTargetUrl;
      }
    } catch (sErr) {
      console.warn("Using offline watermark signing fallback:", sErr);
    }

    // Set granular PDF Document Metadata properties
    const expiryDate = new Date();
    expiryDate.setFullYear(expiryDate.getFullYear() + 3);
    doc.setProperties({
      title: `Official Completion Certificate - ${serviceName} (#${orderIdVal})`,
      subject: `Govt Facilitation & Compliance Verification Registry Certificate - Authority: Amit Online Services, Expiry: ${expiryDate.toISOString().split("T")[0]}, Hash: ${serverHash}`,
      author: "Amit Online Services - Facilitation Authority",
      keywords: `AOS, Certificate, ${serviceName}, Verified, Compliance, ${orderIdVal}, Hash:${serverHash}`,
      creator: "Amit Online Services ERP & PDF Engine v3.6"
    });

    // Certificate Border Frame
    // Outer border (Navy Blue deep)
    doc.setDrawColor(20, 31, 64);
    doc.setLineWidth(1.5);
    doc.rect(8, 8, 194, 281);

    // Inner border (Amber Gold)
    doc.setDrawColor(217, 119, 6);
    doc.setLineWidth(0.5);
    doc.rect(10.5, 10.5, 189, 276);

    // Subtle, diagonal server-side verified digital watermark across the page
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(13);
    doc.setTextColor(220, 225, 235);
    doc.text(serverWatermark, 105, 148, { align: "center", angle: 45 });

    // Corner Ornaments
    doc.line(10.5, 15.5, 15.5, 10.5);
    doc.line(199.5, 15.5, 194.5, 10.5);
    doc.line(10.5, 281.5, 15.5, 286.5);
    doc.line(199.5, 281.5, 194.5, 286.5);

    // Top Header text
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(10);
    doc.setTextColor(115, 125, 140);
    doc.text("AMIT ONLINE SERVICES Facilitation Registry", 105, 24, { align: "center" });

    doc.setDrawColor(226, 232, 240);
    doc.setLineWidth(0.3);
    doc.line(45, 28, 165, 28);

    // Certificate Title
    doc.setFontSize(18);
    doc.setTextColor(20, 31, 64);
    doc.text("VERIFIED CERTIFICATE OF COMPLETION", 105, 42, { align: "center" });

    doc.setFont("Helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(115, 125, 140);
    doc.text(`REGISTRY IDENTIFICATE LICENSE KEY: ${orderIdVal}`, 105, 48, { align: "center" });

    // Star separator
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(14);
    doc.setTextColor(217, 119, 6);
    doc.text("*  *  *", 105, 58, { align: "center" });

    // Declaration Statement
    doc.setFont("Helvetica", "normal");
    doc.setFontSize(11);
    doc.setTextColor(45, 55, 72);
    
    const p1 = "This document officially certifies that the administrative application request or digital signature registration described below has been fully processed, verified, and successfully completed.";
    const p2 = "All associated documentation checks and state registry queries have been executed with absolute source compliance through the secure operations center of Amit Online Services.";
    
    const splitP1 = doc.splitTextToSize(p1, 160);
    const splitP2 = doc.splitTextToSize(p2, 160);

    doc.text(splitP1, 105, 72, { align: "center" });
    doc.text(splitP2, 105, 90, { align: "center" });

    // Main Details Box Grid Card
    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(226, 232, 240);
    doc.rect(20, 114, 170, 78, "FD");

    // Details header
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(20, 31, 64);
    doc.text("REGISTRATION METADATA DOSSIER", 30, 124);
    doc.line(30, 127, 95, 127);

    // Key details
    const labels = [
      { label: "Designated Certificate Holder", val: userEmail },
      { label: "Requested Digitization Class", val: serviceName },
      { label: "Official Verification Status", val: "SUCCESSFULLY COMPLETED / LICENSED" },
      { label: "Authorized Integration Date", val: dateVal },
    ];

    let rowY = 137;
    labels.forEach((itm) => {
      doc.setFont("Helvetica", "bold");
      doc.setFontSize(9);
      doc.setTextColor(115, 125, 140);
      doc.text(itm.label + ":", 30, rowY);

      doc.setFont("Helvetica", "bold");
      doc.setFontSize(9.5);
      if (itm.label.includes("Status")) {
        doc.setTextColor(16, 124, 65);
      } else {
        doc.setTextColor(45, 55, 72);
      }
      doc.text(String(itm.val), 90, rowY);

      rowY += 11;
    });

    // Bottom Section Box
    doc.setFillColor(255, 255, 255);
    doc.rect(20, 206, 170, 64, "S");

    // Signature
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(115, 125, 140);
    doc.text("ISSUING PORTAL REGISTER AUTHORITY", 30, 218);

    doc.setFont("Courier", "oblique");
    doc.setFontSize(14);
    doc.setTextColor(20, 31, 64);
    doc.text("Amit Patel", 35, 236);

    doc.setDrawColor(203, 213, 225);
    doc.line(30, 240, 95, 240);
    
    doc.setFont("Helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(148, 163, 184);
    doc.text("Lead Verification Officer, AOS", 30, 245);
    doc.text(`CR Hash: ${serverHash.substring(0, 18)}...`, 30, 249);

    // Certified Gold Stamp
    doc.setDrawColor(217, 119, 6);
    doc.setLineWidth(0.4);
    doc.circle(112, 238, 12, "S");
    doc.setLineWidth(0.15);
    doc.circle(112, 238, 10.5, "S");
    
    doc.setFont("Helvetica", "bold");
    doc.setFontSize(4.5);
    doc.setTextColor(217, 119, 6);
    doc.text("AMIT ONLINE", 112, 234.5, { align: "center" });
    doc.text("* INTEGRITY *", 112, 238.5, { align: "center" });
    doc.text("VERIFIED", 112, 242.5, { align: "center" });

    // Verifiable QR stamp with server verification payload
    const b64QR = await fetchQrCodeBase64(qrTargetUrl);
    if (b64QR) {
      doc.addImage(b64QR, "PNG", 148, 212, 35, 35);
      doc.setFont("Helvetica", "bold");
      doc.setFontSize(7);
      doc.setTextColor(71, 85, 105);
      doc.text("VERIFIED QR STAMP", 165.5, 251, { align: "center" });
      doc.setFontSize(5.5);
      doc.setTextColor(148, 163, 184);
      doc.text(`AUDIT HASH: ${serverHash.slice(0, 10)}`, 165.5, 254.5, { align: "center" });
    }

    // Legal disclaimer footer
    doc.setFont("Helvetica", "italic");
    doc.setFontSize(7);
    doc.setTextColor(148, 163, 184);
    doc.text("This verified certificate of completion is backed by our synchronized Google Sheets administrative ledger database.", 20, 280);
    doc.text("Any visual mobile device or third-party agent can verify authenticity by scanning the embedded QR integrity check.", 20, 284);

    doc.save(`AOS-Completion-Certificate-${orderIdVal}.pdf`);
    toast.success("Successfully compiled and issued verifiable Completion Certificate!", { id: toastId });
  } catch (err: any) {
    console.error(err);
    toast.error("Failed to generate verifiable PDF certificate: " + err.message, { id: toastId });
  }
};

const toBase64 = (str: string) => {
  try {
    return btoa(unescape(encodeURIComponent(str)));
  } catch (e) {
    return btoa(str);
  }
};

const displayTime = (time: string) => {
  if (!time || time === "-" || time === "Closed") return time;
  if (typeof time === "string" && time.includes("T")) {
    try {
      const date = new Date(time);
      if (!isNaN(date.getTime())) {
        return date.toLocaleTimeString("en-US", {
          hour: "2-digit",
          minute: "2-digit",
          hour12: true,
        });
      }
    } catch (e) {
      return time;
    }
  }
  return time;
};

const getTimeParts = (timeStr: string) => {
  if (!timeStr || timeStr === "-") return { h: 0, m: 0 };
  if (typeof timeStr === "string" && timeStr.includes("T")) {
    try {
      const date = new Date(timeStr);
      if (!isNaN(date.getTime())) {
        return { h: date.getHours(), m: date.getMinutes() };
      }
    } catch (e) {}
  }

  const isPM = timeStr.toUpperCase().includes("PM");
  const cleanTimeStr = timeStr.replace(/\s*(AM|PM|am|pm)\s*/g, "").trim();
  const parts = cleanTimeStr.split(":").map(Number);
  let h = parts[0] || 0;
  const m = parts[1] || 0;

  if (isPM && h !== 12) h += 12;
  if (!isPM && h === 12 && timeStr.toUpperCase().includes("AM")) h = 0;

  return { h, m };
};

