export const AuthContext = React.createContext<AuthContextType | null>(null);

interface ProtectedRouteProps {
  children: React.ReactNode;
  allowedRoles?: Role[];
  isVerifying?: boolean;
}

const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children, allowedRoles, isVerifying = false }) => {
  const savedToken = localStorage.getItem("aos_token");
  const navigate = useNavigate();
  const location = useLocation();

  let userRole: Role = "User";
  try {
    const savedUser = localStorage.getItem("aos_user");
    if (savedUser) {
      const parsed = JSON.parse(savedUser);
      const rawRole = String(parsed?.role || parsed?.Role || "User").toLowerCase().trim();
      if (rawRole === "admin") userRole = "Admin";
      else if (rawRole === "staff") userRole = "Staff";
      else if (rawRole === "developer") userRole = "Developer";
      else userRole = "User";
    }
  } catch {}

  const isAuthorized = savedToken && (!allowedRoles || allowedRoles.includes(userRole));

  useEffect(() => {
    if (isVerifying) return; // Wait until background session verification is complete
    if (!savedToken) {
      toast.error("કૃપા કરીને પહેલા લોગિન કરો. (Authentication required!)");
      // Store intended destination so we can redirect back post-login!
      localStorage.setItem("redirect_to", location.pathname + location.search);
      navigate("/", { replace: true });
      setTimeout(() => {
        window.dispatchEvent(new CustomEvent("open-auth-modal"));
      }, 300);
    } else if (allowedRoles && !allowedRoles.includes(userRole)) {
      toast.error("આ પાનું જોવા માટે તમારી પાસે પરવાનગી નથી. (Access denied!)");
      navigate("/", { replace: true });
    }
  }, [savedToken, userRole, allowedRoles, navigate, location.pathname, location.search, isVerifying]);

  if (isVerifying) {
    return (
      <div className="py-24 flex flex-col items-center justify-center space-y-4">
        <div className="w-12 h-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-slate-500 text-xs font-black uppercase tracking-wider animate-pulse">Authenticating Session...</p>
      </div>
    );
  }

  if (!isAuthorized) {
    return (
      <div className="flex-grow flex items-center justify-center p-20 min-h-[50vh]">
        <div className="flex flex-col items-center gap-3">
          <div className="w-10 h-10 border-4 border-red-600 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-xs text-slate-500 font-bold uppercase tracking-wider">Redirecting safely...</p>
        </div>
      </div>
    );
  }

  return <>{children}</>;
};

export type ServiceType = "Translation" | "Typing" | "OnlineServices" | "FormFilling";

