                      const serviceType = item.service || item.Type || "Standard Translation";
                      const rawStatus = item.status || item.Status || "Pending";
                      const normStatus = rawStatus.toUpperCase().replace(/\s+/g, '_');
                      
                      const isPending = normStatus === "PENDING";
                      const isProcessing = normStatus === "PROCESSING" || normStatus === "SUBMITTED" || normStatus === "UNDER_REVIEW";
                      const isRevision = normStatus === "REVISION_REQUESTED" || normStatus === "NEEDS_REVISION" || normStatus === "QUERY_RAISED";
                      const isCompleted = normStatus === "COMPLETED" || normStatus === "APPROVED/COMPLETED" || normStatus === "APPROVED_COMPLETED" || normStatus === "UPLOADED";
                      
                      const stepIndex = isPending ? 0 : isProcessing ? 1 : isRevision ? 2 : isCompleted ? 3 : 0;
                      
                      const hasOutputLink = item.FinalFileLink || item.finalFileLink;
                      const isPaid = (item.Status && item.Status !== "Unpaid" && item.Status !== "Unverified") || 
                                     (item.status && item.status !== "Unpaid" && item.status !== "Unverified") ||
                                     (item.PaymentID && item.PaymentID !== "");

                      const displayDate = (() => {
                        const val = item.createdAt || item.CreatedAt || item.timestamp || item.Timestamp || item.date || item.Date;
                        if (!val) return "Recently";
                        const parsed = new Date(val);
                        return isNaN(parsed.getTime()) ? "Recently" : parsed.toLocaleDateString();
                      })();

