      doc.text(`Batch Operation Timestamp: ${new Date().toLocaleString('en-IN')}`, 22, 70);
      doc.text(`Batch Reference ID: AOS-BATCH-${Date.now()}`, 22, 78);
      doc.text(`Operator Email / Staff: ${user?.email || "System Admin"}`, 22, 86);

      // Inventory Table Header
